1	"use client";
2	
3	import { useEffect, useMemo, useState } from "react";
4	import { usePathname, useRouter, useSearchParams } from "next/navigation";
5	import type { Dealer, ScoredUnit } from "@/lib/types";
6	import { MODEL_LABEL, GGH_CITIES, MODELS, SUPPORTED_YEARS, type Model } from "@/lib/constants";
7	import { fmtCad } from "@/lib/format";
8	import { effectivePreTaxValue } from "@/lib/scoring";
9	import { DealScoreBadge } from "./DealScoreBadge";
10	import { StatusChip } from "./StatusChip";
11	import { UnitDrawer } from "./UnitDrawer";
12	
13	// EVAP cap is the central 2026 buying-decision tool. We surface three
14	// states per unit: eligible (under cap, $5k applied to OTD), cliff
15	// (within $1,500 over the cap — small accessory cuts may unlock it), and
16	// over-cap (lost rebate, used for sorting and competitor benchmarking).
17	type EvapState = "eligible" | "cliff" | "over";
18	const CAP_CAD = 50000;
19	const CLIFF_BAND_CAD = 1500;
20	function evapStateFor(unit: ScoredUnit): EvapState {
21	  const hasEvap = unit.applicableIncentives.some((i) => i.id.startsWith("fed-evap"));
22	  if (hasEvap) return "eligible";
23	  // Post-OEM-cash effective contract value — matches scoring.ts cap check.
24	  const effective = effectivePreTaxValue(unit, unit.applicableIncentives);
25	  if (effective - CAP_CAD <= CLIFF_BAND_CAD) return "cliff";
26	  return "over";
27	}
28	
29	function EvapChip({ state, unit }: { state: EvapState; unit: ScoredUnit }) {
30	  if (state === "eligible") {
31	    return (
32	      <div
33	        className="text-xxs text-accent mt-0.5 font-normal"
34	        title="Pre-tax transaction value ≤ $50,000 → $5,000 federal EVAP rebate already applied to OTD"
35	      >
36	        EVAP −$5k
37	      </div>
38	    );
39	  }
40	  if (state === "cliff") {
41	    const effective = effectivePreTaxValue(unit, unit.applicableIncentives);
42	    const over = Math.round(effective - CAP_CAD);
43	    return (
44	      <div
45	        className="text-xxs text-warn mt-0.5 font-normal"
46	        title="Within $1,500 of EVAP cap. Trimming dealer add-ons (admin, wheel locks, prep) might unlock the $5k rebate."
47	      >
48	        Cliff +${over}
49	      </div>
50	    );
51	  }
52	  return null;
53	}
54	
55	type Props = {
56	  units: ScoredUnit[];
57	  dealerById: Map<string, Dealer>;
58	  dealerPressureByDealer: Record<string, number>;
59	};
60	
61	type SortKey = "deal" | "otd" | "discount" | "newest" | "oldest";
62	
63	const SORTS: { key: SortKey; label: string }[] = [
64	  { key: "deal", label: "Best deal score" },
65	  { key: "otd", label: "Lowest OTD" },
66	  { key: "discount", label: "Biggest discount vs MSRP" },
67	  { key: "newest", label: "Newest listing" },
68	  { key: "oldest", label: "Longest on lot" },
69	];
70	
71	// Aging signal: any prior-MY unit that's been sitting >90 days. Shoppers can
72	// usually negotiate hardest on these.
73	const CURRENT_MY = Math.max(...SUPPORTED_YEARS);
74	function isAgingOutgoing(year: number, daysOnLot?: number): boolean {
75	  return year < CURRENT_MY && (daysOnLot ?? 0) > 90;
76	}
77	
78	// E-GMP ICCU recall family. Ioniq 5 spans 2025; EV6 + Ioniq 6 stop at 2024.
79	// Source: data/market-intel.json (kept in sync there).
80	function iccuAffected(model: Model, year: number): boolean {
81	  if (model === "EV6" && year >= 2022 && year <= 2024) return true;
82	  if (model === "Ioniq5" && year >= 2022 && year <= 2025) return true;
83	  if (model === "Ioniq6" && year >= 2023 && year <= 2024) return true;
84	  return false;
85	}
86	
87	const VALID_SORTS: SortKey[] = ["deal", "otd", "discount", "newest", "oldest"];
88	
89	const CSV_COLS = [
90	  "model", "year", "trim", "drivetrain", "exteriorColor", "interiorColor",
91	  "msrp", "asking", "otd", "daysOnLot", "status",
92	  "dealerName", "dealerCity", "dealerProvince", "pressure",
93	] as const;
94	
95	function csvEscape(val: string | number | undefined | null): string {
96	  if (val === undefined || val === null) return "";
97	  const s = String(val);
98	  if (s.includes(",") || s.includes('"') || s.includes("\n")) {
99	    return `"${s.replace(/"/g, '""')}"`;
100	  }
101	  return s;
102	}
103	
104	function modelBreakdown(units: ScoredUnit[]): string {
105	  const counts: Record<Model, number> = { EV6: 0, Ioniq5: 0, Ioniq6: 0, EV9: 0, Ioniq9: 0 };
106	  for (const u of units) counts[u.model] += 1;
107	  return (Object.keys(counts) as Model[])
108	    .filter((m) => counts[m] > 0)
109	    .map((m) => `${counts[m]} ${MODEL_LABEL[m]}`)
110	    .join(", ");
111	}
112	
113	function activeFilterChips(s: {
114	  model: Model | "all";
115	  year: number | "all";
116	  drivetrain: "RWD" | "AWD" | "all";
117	  region: "ggh" | "on" | "all";
118	  maxPrice: number | "";
119	  pressureOnly: boolean;
120	  evapOnly: boolean;
121	  query: string;
122	}): { key: string; label: string }[] {
123	  const out: { key: string; label: string }[] = [];
124	  if (s.model !== "all") out.push({ key: "model", label: MODEL_LABEL[s.model] });
125	  if (s.year !== "all") out.push({ key: "year", label: `MY ${s.year}` });
126	  if (s.drivetrain !== "all") out.push({ key: "drivetrain", label: s.drivetrain });
127	  if (s.region !== "ggh") out.push({ key: "region", label: s.region === "on" ? "All Ontario" : "All Canada" });
128	  if (s.maxPrice !== "") out.push({ key: "maxPrice", label: `≤ $${s.maxPrice.toLocaleString("en-CA")}` });
129	  if (s.pressureOnly) out.push({ key: "pressureOnly", label: "High pressure" });
130	  if (s.evapOnly) out.push({ key: "evapOnly", label: "EVAP eligible" });
131	  if (s.query.trim()) out.push({ key: "query", label: `"${s.query.trim()}"` });
132	  return out;
133	}
134	
135	function exportCsv(
136	  units: ScoredUnit[],
137	  dealerById: Map<string, Dealer>,
138	  pressureByDealer: Record<string, number>,
139	) {
140	  const header = CSV_COLS.join(",");
141	  const rows = units.map((u) => {
142	    const d = dealerById.get(u.dealerId);
143	    return [
144	      u.model, u.year, u.trim, u.drivetrain, u.exteriorColor, u.interiorColor,
145	      u.msrp, u.dealerAskingPrice, u.otdCad, u.daysOnLot ?? "", u.status,
146	      d?.name ?? "", d?.city ?? "", d?.province ?? "", pressureByDealer[u.dealerId] ?? 0,
147	    ].map(csvEscape).join(",");
148	  });
149	  const csv = [header, ...rows].join("\n");
150	  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
151	  const url = URL.createObjectURL(blob);
152	  const today = new Date().toISOString().slice(0, 10).replace(/-/g, "");
153	  const a = document.createElement("a");
154	  a.href = url;
155	  a.download = `ev-inventory-${today}.csv`;
156	  document.body.appendChild(a);
157	  a.click();
158	  document.body.removeChild(a);
159	  URL.revokeObjectURL(url);
160	}
