162	export function InventoryTable({ units, dealerById, dealerPressureByDealer }: Props) {
163	  const router = useRouter();
164	  const pathname = usePathname();
165	  const searchParams = useSearchParams();
166	
167	  const initial = useMemo(() => {
168	    const m = searchParams.get("model");
169	    const y = searchParams.get("year");
170	    const dt = searchParams.get("dt");
171	    const rg = searchParams.get("region");
172	    const mp = searchParams.get("maxOtd");
173	    const po = searchParams.get("pressure");
174	    const ev = searchParams.get("evap");
175	    const so = searchParams.get("sort");
176	    const q = searchParams.get("q");
177	    const uid = searchParams.get("u");
178	    return {
179	      model: (m && (MODELS as readonly string[]).includes(m) ? (m as Model) : "all") as Model | "all",
180	      year: (y && SUPPORTED_YEARS.map(String).includes(y) ? Number(y) : "all") as number | "all",
181	      drivetrain: (dt === "RWD" || dt === "AWD" ? dt : "all") as "RWD" | "AWD" | "all",
182	      region: (rg === "on" || rg === "all" ? rg : "ggh") as "ggh" | "on" | "all",
183	      maxPrice: (mp && !Number.isNaN(Number(mp)) ? Number(mp) : "") as number | "",
184	      pressureOnly: po === "1",
185	      evapOnly: ev === "1",
186	      sort: ((so && VALID_SORTS.includes(so as SortKey)) ? (so as SortKey) : "deal") as SortKey,
187	      query: q ?? "",
188	      unitId: uid ?? null,
189	    };
190	    // eslint-disable-next-line react-hooks/exhaustive-deps
191	  }, []);
192	
193	  const [model, setModel] = useState<Model | "all">(initial.model);
194	  const [year, setYear] = useState<number | "all">(initial.year);
195	  const [drivetrain, setDrivetrain] = useState<"RWD" | "AWD" | "all">(initial.drivetrain);
196	  const [region, setRegion] = useState<"ggh" | "on" | "all">(initial.region);
197	  const [maxPrice, setMaxPrice] = useState<number | "">(initial.maxPrice);
198	  const [pressureOnly, setPressureOnly] = useState(initial.pressureOnly);
199	  const [evapOnly, setEvapOnly] = useState(initial.evapOnly);
200	  const [sort, setSort] = useState<SortKey>(initial.sort);
201	  const [query, setQuery] = useState<string>(initial.query);
202	  const [selectedId, setSelectedId] = useState<string | null>(initial.unitId);
203	
204	  useEffect(() => {
205	    const p = new URLSearchParams();
206	    if (model !== "all") p.set("model", model);
207	    if (year !== "all") p.set("year", String(year));
208	    if (drivetrain !== "all") p.set("dt", drivetrain);
209	    if (region !== "ggh") p.set("region", region);
210	    if (maxPrice !== "") p.set("maxOtd", String(maxPrice));
211	    if (pressureOnly) p.set("pressure", "1");
212	    if (evapOnly) p.set("evap", "1");
213	    if (sort !== "deal") p.set("sort", sort);
214	    if (query.trim()) p.set("q", query.trim());
215	    if (selectedId) p.set("u", selectedId);
216	    const qs = p.toString();
217	    router.replace(qs ? `${pathname}?${qs}` : pathname, { scroll: false });
218	  }, [model, year, drivetrain, region, maxPrice, pressureOnly, evapOnly, sort, query, selectedId, pathname, router]);
219	
220	  const filtered = useMemo(() => {
221	    const q = query.trim().toLowerCase();
222	    return units
223	      .filter((u) => {
224	        if (model !== "all" && u.model !== model) return false;
225	        if (year !== "all" && u.year !== year) return false;
226	        if (drivetrain !== "all" && u.drivetrain !== drivetrain) return false;
227	        const dealer = dealerById.get(u.dealerId);
228	        if (!dealer) return false;
229	        if (region === "ggh" && (dealer.province !== "ON" || !GGH_CITIES.includes(dealer.city))) return false;
230	        if (region === "on" && dealer.province !== "ON") return false;
231	        if (maxPrice && u.otdCad > Number(maxPrice)) return false;
232	        if (pressureOnly && (dealerPressureByDealer[dealer.id] ?? 0) < 50) return false;
233	        if (evapOnly && evapStateFor(u) !== "eligible") return false;
234	        if (q) {
235	          const hay = `${u.trim} ${u.exteriorColor} ${u.interiorColor} ${u.vin ?? ""} ${u.stockNumber ?? ""} ${dealer.name} ${dealer.city}`.toLowerCase();
236	          if (!hay.includes(q)) return false;
237	        }
238	        return true;
239	      })
240	      .sort((a, b) => {
241	        if (sort === "deal") return b.dealScore - a.dealScore;
242	        if (sort === "otd") return a.otdCad - b.otdCad;
243	        if (sort === "discount") {
244	          const da = (a.msrp - a.dealerAskingPrice) / a.msrp;
245	          const db = (b.msrp - b.dealerAskingPrice) / b.msrp;
246	          return db - da;
247	        }
248	        if (sort === "newest") return new Date(b.firstSeen).getTime() - new Date(a.firstSeen).getTime();
249	        return new Date(a.firstSeen).getTime() - new Date(b.firstSeen).getTime();
250	      });
251	  }, [units, dealerById, dealerPressureByDealer, model, year, drivetrain, region, maxPrice, pressureOnly, sort, query]);
252	
253	  const selected = useMemo(
254	    () => (selectedId ? units.find((u) => u.id === selectedId) ?? null : null),
255	    [selectedId, units],
256	  );
257	
258	  // Cheapest other listing of same model+year+trim — anchors the price ask in
259	  // the negotiation draft.
260	  const comparable = useMemo(() => {
261	    if (!selected) return undefined;
262	    return units
263	      .filter((u) =>
264	        u.id !== selected.id &&
265	        u.model === selected.model &&
266	        u.year === selected.year &&
267	        u.trim === selected.trim,
268	      )
269	      .sort((a, b) => a.otdCad - b.otdCad)[0];
270	  }, [selected, units]);
271	
272	  return (
273	    <div className="card overflow-hidden">
274	      <div className="p-3 border-b border-border flex flex-wrap items-center gap-2 text-xs">
275	        <input
276	          type="search"
277	          value={query}
278	          onChange={(e) => setQuery(e.target.value)}
279	          placeholder="Search trim, color, dealer, VIN…"
280	          className="px-2 py-1.5 w-56"
281	        />
282	        <select
283	          value={model}
284	          onChange={(e) => setModel(e.target.value as Model | "all")}
285	          className="px-2 py-1.5"
286	        >
287	          <option value="all">All models</option>
288	          {MODELS.map((m) => (
289	            <option key={m} value={m}>{MODEL_LABEL[m]}</option>
290	          ))}
291	        </select>
292	        <select
293	          value={year}
294	          onChange={(e) => setYear(e.target.value === "all" ? "all" : Number(e.target.value))}
295	          className="px-2 py-1.5"
296	        >
297	          <option value="all">All years</option>
298	          <option value={2024}>2024</option>
299	          <option value={2025}>2025</option>
300	          <option value={2026}>2026</option>
301	        </select>
302	        <select
303	          value={drivetrain}
304	          onChange={(e) => setDrivetrain(e.target.value as "RWD" | "AWD" | "all")}
305	          className="px-2 py-1.5"
306	        >
307	          <option value="all">RWD + AWD</option>
308	          <option value="RWD">RWD only</option>
309	          <option value="AWD">AWD only</option>
310	        </select>
311	        <select
312	          value={region}
313	          onChange={(e) => setRegion(e.target.value as "ggh" | "on" | "all")}
314	          className="px-2 py-1.5"
315	        >
