365	          className="px-2 py-1.5 border border-border rounded text-fg-muted hover:bg-bg-hover"
366	          disabled={filtered.length === 0}
367	        >
368	          Export CSV
369	        </button>
370	      </div>
371	      {activeFilterChips({ model, year, drivetrain, region, maxPrice, pressureOnly, evapOnly, query }).length > 0 && (
372	        <div className="px-3 py-2 border-b border-border flex flex-wrap items-center gap-1.5 text-xxs">
373	          <span className="text-fg-subtle uppercase tracking-wide">Active:</span>
374	          {activeFilterChips({ model, year, drivetrain, region, maxPrice, pressureOnly, evapOnly, query }).map((c) => (
