422	          </thead>
423	          <tbody>
424	            {filtered.map((u) => {
425	              const dealer = dealerById.get(u.dealerId);
426	              const pressure = dealerPressureByDealer[u.dealerId] ?? 0;
427	              const isActive = u.id === selectedId;
428	              return (
429	                <tr
430	                  key={u.id}
431	                  className={`border-t border-border cursor-pointer ${isActive ? "bg-accent-dim/20" : "card-hover"}`}
432	                  onClick={() => setSelectedId(u.id)}
433	                >
434	                  <td className="px-3 py-2"><DealScoreBadge score={u.dealScore} /></td>
435	                  <td className="px-3 py-2">
436	                    <div className="font-medium">{MODEL_LABEL[u.model]}</div>
437	                    <div className="text-xxs text-fg-muted">{u.trim} · {u.drivetrain}</div>
438	                  </td>
439	                  <td className="px-3 py-2 num">{u.year}</td>
440	                  <td className="px-3 py-2 text-xs">
441	                    <div>{u.exteriorColor}</div>
442	                    <div className="text-fg-subtle">{u.interiorColor}</div>
443	                  </td>
444	                  <td className="px-3 py-2 text-right num">{fmtCad(u.msrp)}</td>
445	                  <td className="px-3 py-2 text-right num">
446	                    {fmtCad(u.dealerAskingPrice)}
447	                    {u.dealerAskingPrice < u.msrp && (
448	                      <div className="text-xxs text-accent">
449	                        −{fmtCad(u.msrp - u.dealerAskingPrice)}
450	                      </div>
451	                    )}
452	                  </td>
453	                  <td className="px-3 py-2 text-right num font-medium">
454	                    {fmtCad(u.otdCad)}
455	                    <EvapChip state={evapStateFor(u)} unit={u} />
