459	                    <StatusChip status={u.status} />
460	                    {isAgingOutgoing(u.year, u.daysOnLot) && (
461	                      <span className="chip-warn block w-fit">Aging MY{String(u.year).slice(-2)}</span>
462	                    )}
463	                    {iccuAffected(u.model, u.year) && (
464	                      <span
465	                        className="chip-bad block w-fit"
466	                        title="E-GMP ICCU recall family. Demand written confirmation that ICCU software flash + module inspection have been completed before contracting. 15-yr/290k-km warranty extension applies."
467	                      >
468	                        ICCU recall
469	                      </span>
470	                    )}
471	                  </td>
472	                  <td className="px-3 py-2 text-xs">
473	                    <div className="font-medium">{dealer?.name ?? "—"}</div>
474	                    <div className="text-fg-subtle">{dealer?.city}, {dealer?.province}</div>
475	                  </td>
476	                  <td className="px-3 py-2 text-right num">
477	                    <span className={pressure >= 70 ? "text-accent" : pressure >= 40 ? "text-warn" : "text-fg-muted"}>
478	                      {pressure}
479	                    </span>
480	                  </td>
481	                </tr>
482	              );
483	            })}
484	            {filtered.length === 0 && (
485	              <tr>
486	                <td colSpan={11} className="px-3 py-12 text-center text-fg-muted">
487	                  No units match these filters.
488	                </td>
489	              </tr>
490	            )}
491	          </tbody>
492	        </table>
493	      </div>
494	      <UnitDrawer
495	        unit={selected}
496	        dealer={selected ? dealerById.get(selected.dealerId) : undefined}
497	        pressure={selected ? dealerPressureByDealer[selected.dealerId] ?? 0 : 0}
498	        comparable={comparable}
499	        comparableDealer={comparable ? dealerById.get(comparable.dealerId) : undefined}
500	        onClose={() => setSelectedId(null)}
501	        onNavigate={(dir) => {
502	          if (!selected || filtered.length === 0) return;
503	          const idx = filtered.findIndex((u) => u.id === selected.id);
504	          if (idx === -1) return;
505	          const next = (idx + dir + filtered.length) % filtered.length;
506	          setSelectedId(filtered[next].id);
507	        }}
508	        position={
509	          selected
510	            ? {
511	                index: Math.max(0, filtered.findIndex((u) => u.id === selected.id)),
512	                total: filtered.length,
