              <>
                <button
                  type="button"
                  onClick={() => onNavigate(-1)}
                  className="text-fg-muted hover:text-fg px-2 py-1"
                  aria-label="Previous unit"
                  title="Previous (←)"
                >
                  ‹
                </button>
                <span className="text-xxs text-fg-subtle num">
