              {dealer.phone && <div className="text-fg-muted">{dealer.phone}</div>}
              <div className="text-xxs text-fg-subtle pt-1">
                Pressure score:{" "}
                <span className={pressure >= 70 ? "text-accent" : pressure >= 40 ? "text-warn" : "text-fg-muted"}>
