  );
}

function Row({ label, value, accentNegative }: { label: string; value: number; accentNegative?: boolean }) {
  const cls = accentNegative && value < 0 ? "num text-accent" : "num text-fg-muted";
  return (
    <div className="flex justify-between">
      <dt className="text-fg-muted">{label}</dt>
      <dd className={cls}>{fmtCad(value)}</dd>
    </div>
  );
}

function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(text);
          setCopied(true);
          setTimeout(() => setCopied(false), 1500);
        } catch {
          // clipboard blocked; ignore
        }
      }}
      className="text-xxs px-2 py-1 border border-border rounded hover:bg-bg-hover text-fg-muted"
    >
      {copied ? "Copied" : "Copy"}
    </button>
  );
}

// Caveman-style draft: short, blunt, fact-anchored. Days-on-lot, pressure score,
// and comparable cheapest unit are required injected facts.
function buildEmailDraft(
  unit: ScoredUnit,
  dealer: Dealer | undefined,
  pressure: number,
  comparable: ScoredUnit | undefined,
  comparableDealer: Dealer | undefined,
): string {
  const greet = dealer ? `Hi ${dealer.name} team,` : "Hi,";
  const stockLine = unit.stockNumber ? `stock #${unit.stockNumber}` : unit.vin ? `VIN ${unit.vin}` : "this unit";
  const days = unit.daysOnLot ?? 0;

  const aging = days > 90
    ? `Listing shows ${days} days on lot. That's aging stock.`
    : days > 30
      ? `Listing shows ${days} days on lot.`
      : "";

  const pressureNote = pressure >= 70
    ? `Your dealership has heavy ${unit.model} inventory right now (pressure score ${pressure}/100).`
    : pressure >= 40
      ? `Inventory depth here is moderate (pressure score ${pressure}/100).`
      : "";

  const compLine = comparable
    ? `Comparable ${comparable.year} ${comparable.trim} listed at ${fmtCad(comparable.dealerAskingPrice)} ${comparableDealer ? `(${comparableDealer.name}, ${comparableDealer.city})` : ""}. Asking ${fmtCad(comparable.otdCad)} OTD there.`
    : "";

  const askDelta = comparable && comparable.otdCad < unit.otdCad
    ? `Looking to match or beat ${fmtCad(comparable.otdCad)} OTD.`
    : `Looking for OTD under ${fmtCad(Math.round(unit.otdCad * 0.97))}.`;

  // EVAP context. The cap is the central 2026 negotiation handle. Effective
  // contract value subtracts known OEM cash so a $58k Limited AWD with $16k
  // bonus reads as a $42k contract (and qualifies for EVAP). If unit is
  // just over the cap post-bonus, ask the dealer to trim accessories/admin.
  const effectivePreTax = effectivePreTaxValue(unit, unit.applicableIncentives);
  const evapEligible = unit.applicableIncentives.some((i) => i.id.startsWith("fed-evap"));
  const overCap = effectivePreTax - 50000;
  const evapLine = evapEligible
    ? `Effective pre-tax contract value of ${fmtCad(effectivePreTax)} qualifies for the $5,000 federal EVAP rebate — already in the OTD figure above.`
    : overCap > 0 && overCap <= 1500
      ? `Effective pre-tax contract value of ${fmtCad(effectivePreTax)} sits ${fmtCad(overCap)} over the $50,000 EVAP cap. Trimming admin/wheel-locks/prep to bring it under the cap unlocks $5,000 in federal rebate (~${fmtCad(Math.round(5000 * 1.13))} after Ontario HST).`
      : overCap > 1500
        ? `Note this trim is ${fmtCad(overCap)} over the federal EVAP cap, so it doesn't get the $5,000 rebate. Equivalent post-rebate competitor: Equinox EV 2LT AWD at ${fmtCad(44699)} OTD-ish (Chevy MSRP $49,699 minus $5,000 EVAP).`
        : "";

  const lines = [
    greet,
    "",
    `Interested in your ${unit.year} ${MODEL_LABEL[unit.model]} ${unit.trim} ${unit.drivetrain} (${stockLine}).`,
    "",
    aging,
    pressureNote,
    compLine,
    evapLine,
    "",
    askDelta,
    "Cash deal, financing pre-approved, ready to sign this week if numbers work.",
    "",
    "What's your best out-the-door?",
    "",
    "Thanks.",
  ].filter((l) => l !== undefined);

  return lines.join("\n").replace(/\n{3,}/g, "\n\n");
}

import Link from "next/link";
import { loadScoredUnits, loadMeta, loadUsedListings, loadSpecs, computeUsedMarketStats } from "@/lib/data";
import { computeKpis, dealerPressureMap, inGGH, provinceRollup } from "@/lib/aggregations";
import { MODELS, MODEL_LABEL, MODEL_BRAND, PROVINCE_NAMES } from "@/lib/constants";
import { fmtCad, relativeDays } from "@/lib/format";
import { effectivePreTaxValue } from "@/lib/scoring";
import { KpiTile } from "@/components/KpiTile";
import { DealScoreBadge } from "@/components/DealScoreBadge";
import type { ModelKpis } from "@/lib/aggregations";

export const dynamic = "force-static";

export default async function Dashboard() {
  const { units, dealers, dealerById, incentives } = await loadScoredUnits();
  const meta = await loadMeta();
  const [usedListings, specs] = await Promise.all([loadUsedListings(), loadSpecs()]);
  const usedStats = computeUsedMarketStats(usedListings, specs);
  const kpis = computeKpis(units, dealerById, [...MODELS]);
  const pressure = dealerPressureMap(units, dealers);
  const provinces = provinceRollup(units, dealerById);

  const topDeals = [...units].sort((a, b) => b.dealScore - a.dealScore).slice(0, 8);
  const gghCount = units.filter((u) => inGGH(u, dealerById)).length;
  const activeIncentives = incentives.filter((i) => i.status === "active").length;
  const pausedIncentives = incentives.filter((i) => i.status === "paused").length;

  // EVAP-aware shopping signals. Eligible = unit's applicable list contains a
  // fed-evap-* row (cap test happens upstream in scoring.ts). Cliff = within
  // $1,500 over the cap → trimming dealer add-ons may unlock the rebate.
  const evapEligibleUnits = units.filter((u) => u.applicableIncentives.some((i) => i.id.startsWith("fed-evap")));
  const cliffUnits = units.filter((u) => {
    if (u.applicableIncentives.some((i) => i.id.startsWith("fed-evap"))) return false;
    const effective = effectivePreTaxValue(u, u.applicableIncentives);
    return effective > 50000 && effective - 50000 <= 1500;
  });
  const lowestEvapOtd = evapEligibleUnits.length
    ? Math.min(...evapEligibleUnits.map((u) => u.otdCad))
    : null;

  const highPressureDealers = dealers
    .map((d) => ({ d, score: pressure[d.id] ?? 0, count: units.filter((u) => u.dealerId === d.id).length }))
    .filter((row) => row.count > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, 5);

  return (
    <div className="space-y-8">
      <section className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">EV market dashboard — Canada</h1>
          <p className="text-sm text-fg-muted">
            Kia EV6 · Hyundai Ioniq 5 · Hyundai Ioniq 6 (incl. N + GT trims). GTA-prioritized.
          </p>
        </div>
        <div className="text-xxs text-fg-subtle text-right space-y-0.5">
          <div>Inventory updated {relativeDays(meta.unitsUpdatedAt)}</div>
          <div>Incentives updated {relativeDays(meta.incentivesUpdatedAt)}</div>
          <div>{meta.snapshotCount} historical snapshot{meta.snapshotCount === 1 ? "" : "s"}</div>
        </div>
      </section>

      <section className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <KpiTile
          label="Units in GTA / GGH"
          value={gghCount}
          sub={`${units.length} nationwide`}
          accent="accent"
        />
        <KpiTile
          label="EVAP-eligible units"
          value={evapEligibleUnits.length}
          sub={lowestEvapOtd ? `Lowest OTD ${fmtCad(lowestEvapOtd)}` : "none under $50k cap"}
          accent={evapEligibleUnits.length > 0 ? "accent" : undefined}
        />
        <KpiTile
          label="Dealers tracked"
          value={dealers.length}
          sub={`${dealers.filter((d) => d.province === "ON").length} in Ontario`}
        />
        <KpiTile
          label="Best deal score"
          value={topDeals[0]?.dealScore ?? "—"}
          sub={topDeals[0] ? `${MODEL_LABEL[topDeals[0].model]} · ${topDeals[0].trim}` : "no units"}
          accent="accent"
        />
