      <section className="card overflow-hidden">
        <div className="px-4 py-3 border-b border-border flex items-baseline justify-between">
          <h2 className="text-sm uppercase tracking-wide text-fg-subtle">Used-market negotiation leverage</h2>
          <span className="text-xxs text-fg-subtle">2023-2024 listings · {usedListings.length} units · AutoTrader 2026-05-01</span>
        </div>
        <table className="w-full">
          <thead className="bg-bg-subtle text-xxs uppercase text-fg-subtle">
            <tr>
              <th className="px-3 py-2 text-left">Model</th>
              <th className="px-3 py-2 text-right">Used count</th>
              <th className="px-3 py-2 text-right">Used median</th>
              <th className="px-3 py-2 text-right">Used range</th>
              <th className="px-3 py-2 text-right">Median km</th>
              <th className="px-3 py-2 text-right">New MSRP floor</th>
              <th className="px-3 py-2 text-right">Retention</th>
            </tr>
          </thead>
          <tbody>
            {usedStats.map((s) => (
              <tr key={s.model} className="border-t border-border">
                <td className="px-3 py-2">{MODEL_LABEL[s.model]}</td>
                <td className="px-3 py-2 text-right num">{s.count}</td>
                <td className="px-3 py-2 text-right num font-medium">{fmtCad(s.medianPriceCad)}</td>
                <td className="px-3 py-2 text-right num text-fg-subtle">{fmtCad(s.minPriceCad)} – {fmtCad(s.maxPriceCad)}</td>
                <td className="px-3 py-2 text-right num text-fg-subtle">{s.medianKm.toLocaleString()}</td>
                <td className="px-3 py-2 text-right num text-fg-subtle">{s.newMsrpFloorCad ? fmtCad(s.newMsrpFloorCad) : "—"}</td>
                <td className={`px-3 py-2 text-right num font-medium ${s.retentionPercent != null && s.retentionPercent < 70 ? "text-bad" : ""}`}>
                  {s.retentionPercent != null ? `${s.retentionPercent}%` : "—"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        <p className="px-4 py-3 text-xxs text-fg-subtle border-t border-border">
          Retention = used median ÷ lowest new MSRP for the same model. Lower = steeper depreciation = stronger lever when arguing a new-car discount.
        </p>
      </section>

      <section className="card overflow-hidden">
        <div className="px-4 py-3 border-b border-border">
          <h2 className="text-sm uppercase tracking-wide text-fg-subtle">National stock by province</h2>
        </div>
        <table className="w-full">
          <thead className="bg-bg-subtle text-xxs uppercase text-fg-subtle">
            <tr>
              <th className="px-3 py-2">Province</th>
              <th className="px-3 py-2 text-right">Total</th>
              {MODELS.map((m) => (
                <th key={m} className="px-3 py-2 text-right">{MODEL_LABEL[m]}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {provinces.map((p) => (
              <tr key={p.province} className="border-t border-border">
                <td className="px-3 py-2">{PROVINCE_NAMES[p.province as keyof typeof PROVINCE_NAMES] ?? p.province}</td>
                <td className="px-3 py-2 text-right num font-medium">{p.count}</td>
                {MODELS.map((m) => (
                  <td key={m} className="px-3 py-2 text-right num">{p.countByModel[m]}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </section>
    </div>
  );
}

const MIX_COLORS: Record<string, string> = {
  EV6: "bg-accent",
  Ioniq5: "bg-warn",
  Ioniq6: "bg-fg-muted",
  EV9: "bg-accent-strong",
  Ioniq9: "bg-bad",
};

function ModelMixBars({ kpis }: { kpis: ModelKpis[] }) {
  const totalCanada = kpis.reduce((s, k) => s + k.totalCanada, 0);
  const totalGgh = kpis.reduce((s, k) => s + k.totalGgh, 0);
  return (
    <div className="card p-4 space-y-4">
      <MixRow label="Greater Golden Horseshoe" total={totalGgh} kpis={kpis} field="totalGgh" />
      <MixRow label="Canada-wide" total={totalCanada} kpis={kpis} field="totalCanada" />
      <div className="flex gap-4 text-xxs text-fg-subtle pt-1">
        {kpis.map((k) => (
          <span key={k.model} className="flex items-center gap-1.5">
            <span className={`inline-block w-2 h-2 rounded ${MIX_COLORS[k.model]}`} />
            {MODEL_LABEL[k.model]}
          </span>
        ))}
      </div>
    </div>
  );
}

function MixRow({
  label,
  total,
  kpis,
  field,
}: {
  label: string;
  total: number;
  kpis: ModelKpis[];
  field: "totalCanada" | "totalGgh";
}) {
  return (
    <div>
      <div className="flex items-baseline justify-between text-xxs text-fg-subtle mb-1">
        <span className="uppercase tracking-wide">{label}</span>
        <span className="num">{total} unit{total === 1 ? "" : "s"}</span>
      </div>
      <div className="flex w-full h-3 rounded overflow-hidden bg-bg-subtle">
        {total === 0 ? null : kpis.map((k) => {
          const count = k[field];
          if (count === 0) return null;
          const pct = (count / total) * 100;
          return (
            <div
              key={k.model}
              className={MIX_COLORS[k.model]}
              style={{ width: `${pct}%` }}
              title={`${MODEL_LABEL[k.model]}: ${count} (${pct.toFixed(0)}%)`}
            />
          );
        })}
      </div>
    </div>
  );
}

