1	import { ON_DEALER_FEES, PROVINCE_TAX, bcPstRateFor } from "./constants";
2	import type {
3	  Dealer,
4	  Incentive,
5	  IncentiveLine,
6	  IncentiveScope,
7	  InventoryUnit,
8	  ScoredUnit,
9	} from "./types";
10	
11	export type { IncentiveLine } from "./types";
12	
13	// E-GMP cars are assembled in Korea (and US for some Ioniq 5 trims) so they
14	// are NOT Canadian-made. EVAP cap applies in full to every unit we track.
15	const E_GMP_IS_IMPORTED = true;
16	
17	// Cash incentive scopes that come off the OTD as a contract-level deduction.
18	// lease_promo / finance_promo are APR-based (modeled as monthly payment, not
19	// price), and charger_install is a separate budget line.
20	const OTD_ELIGIBLE_SCOPES: ReadonlySet<IncentiveScope> = new Set([
21	  "federal",
22	  "provincial",
23	  "manufacturer_cash",
24	  "loyalty",
25	  "conquest",
26	]);
27	
28	// Programs that are scoped "provincial" or similar but that pay out as a
29	// loan-rate or post-purchase reimbursement, not as a contract-line rebate.
30	// These should not be subtracted from OTD even though appliesTo matches.
31	const NON_OTD_INCENTIVE_IDS: ReadonlySet<string> = new Set([
32	  "nl-takecharge-nlcu-loan-rebate-2026",
33	]);
34	
35	// Pre-tax transaction value used for cap eligibility. Excludes sales tax
36	// (matches Transport Canada's EVAP rule).
37	export function preTaxTransactionValue(unit: InventoryUnit): number {
38	  return (
39	    unit.dealerAskingPrice +
40	    unit.freightPdi +
41	    ON_DEALER_FEES.airConditioningExciseTax
42	  );
43	}
44	
45	// Pre-tax value AFTER manufacturer cash has been applied. EVAP's $50k cap is
46	// measured against the contract value at signing — a $58k Ioniq 6 with a
47	// $16k OEM bonus is a $42k contract and therefore EVAP-eligible.
48	export function effectivePreTaxValue(
49	  unit: InventoryUnit,
50	  applicable: Incentive[] = [],
51	): number {
52	  const oemCash = applicable
53	    .filter(
54	      (i) =>
55	        i.scope === "manufacturer_cash" &&
56	        i.status === "active" &&
57	        i.amountCad !== undefined,
58	    )
59	    .reduce((s, i) => s + (i.amountCad ?? 0), 0);
60	  return Math.max(0, preTaxTransactionValue(unit) - oemCash);
61	}
62	
63	export function evapEligibleAmount(
64	  unit: InventoryUnit,
65	  evap: Incentive | undefined,
66	  applicable: Incentive[] = [],
67	): number {
68	  if (!evap || evap.status !== "active") return 0;
69	  const cap = evap.transactionValueCapCad;
70	  if (cap !== undefined && evap.capAppliesToImported && E_GMP_IS_IMPORTED) {
71	    if (effectivePreTaxValue(unit, applicable) > cap) return 0;
72	  }
73	  // Cash/finance/48mo+ lease assumption (default in the dashboard view).
74	  return evap.leaseTermProration?.["48"] ?? evap.amountCad ?? 0;
75	}
76	
77	// Walks the matched-applicable list and returns the per-line dollar amounts
78	// that come off the OTD, plus the total. EVAP's lease-term proration and
79	// post-OEM-cash cap check live inside evapEligibleAmount.
80	export function stackedOtdIncentives(
81	  unit: InventoryUnit,
82	  applicable: Incentive[],
83	): { lines: IncentiveLine[]; totalCad: number } {
84	  const lines: IncentiveLine[] = [];
85	  for (const inc of applicable) {
86	    if (NON_OTD_INCENTIVE_IDS.has(inc.id)) continue;
87	    if (!OTD_ELIGIBLE_SCOPES.has(inc.scope)) continue;
88	    if (inc.status !== "active") continue;
89	    let amount = 0;
90	    if (inc.id.startsWith("fed-evap")) {
91	      amount = evapEligibleAmount(unit, inc, applicable);
92	    } else if (inc.amountCad !== undefined) {
93	      amount = inc.amountCad;
94	    }
95	    if (amount > 0) {
96	      lines.push({ id: inc.id, name: inc.name, scope: inc.scope, amountCad: amount });
97	    }
98	  }
99	  const totalCad = +lines.reduce((s, l) => s + l.amountCad, 0).toFixed(2);
100	  return { lines, totalCad };
101	}
102	
103	// Sales tax handler. ON: flat HST. BC: 5% GST + progressive PST bracket
104	// keyed off the pre-tax base. Other provinces: flat PROVINCE_TAX rate.
105	function salesTaxFor(province: string, preTaxBase: number, vehiclePrice: number): number {
106	  if (province === "BC") {
107	    const gst = preTaxBase * 0.05;
108	    const pst = vehiclePrice * bcPstRateFor(vehiclePrice);
109	    return +(gst + pst).toFixed(2);
110	  }
111	  const rate = PROVINCE_TAX[province as keyof typeof PROVINCE_TAX] ?? 0.13;
112	  return +(preTaxBase * rate).toFixed(2);
113	}
114	
115	// True out-the-door math for a single unit. The buyer-relevant total.
116	// All cash-equivalent incentives (federal EVAP, provincial rebates,
117	// manufacturer cash, loyalty/conquest) are subtracted as contract-line
118	// deductions. APR-based promos and charger-install programs are excluded.
119	// Sales tax stacks on top of the pre-tax base (vehicle + freight + AC
120	// excise) per CRA guidance; OMVIC, RDPRM, tire stewardship, and licensing
121	// are typically post-tax line items.
122	export function computeOtd(
123	  unit: InventoryUnit,
124	  dealer: Dealer,
125	  applicable: Incentive[] = [],
126	): ScoredUnit["otdBreakdown"] {
127	  const dealerAdjustment = unit.dealerAskingPrice - unit.msrp;
128	  const preTaxBase = preTaxTransactionValue(unit);
129	  const salesTax = salesTaxFor(dealer.province, preTaxBase, unit.dealerAskingPrice);
130	
131	  const stack = stackedOtdIncentives(unit, applicable);
132	
133	  const total =
134	    preTaxBase +
135	    salesTax +
136	    ON_DEALER_FEES.rdprmFee +
137	    ON_DEALER_FEES.omvicFee +
138	    ON_DEALER_FEES.tireStewardshipFee +
139	    ON_DEALER_FEES.govLicensingEstimate -
140	    stack.totalCad;
141	
142	  return {
143	    msrp: unit.msrp,
144	    freightPdi: unit.freightPdi,
145	    dealerAdjustment,
146	    acExciseTax: ON_DEALER_FEES.airConditioningExciseTax,
147	    rdprm: ON_DEALER_FEES.rdprmFee,
148	    omvic: ON_DEALER_FEES.omvicFee,
149	    tireStewardship: ON_DEALER_FEES.tireStewardshipFee,
150	    govLicensing: ON_DEALER_FEES.govLicensingEstimate,
151	    salesTax,
152	    incentivesApplied: stack.lines,
153	    incentivesTotalCad: stack.totalCad,
154	    total: +total.toFixed(2),
155	  };
156	}
157	
158	// Filter incentives down to ones that match this unit + dealer. Used both
159	// for the deal-score stack term and for the per-unit detail panel. EVAP
160	// transaction-value cap is enforced here so over-cap units don't show the
161	// rebate as "applicable." Cap is measured against the post-OEM-cash contract
162	// value, so a $58k Limited AWD with a $16k OEM bonus still gets EVAP.
163	export function applicableIncentives(
164	  unit: InventoryUnit,
165	  dealer: Dealer,
166	  incentives: Incentive[],
167	): Incentive[] {
168	  // First pass: filter on appliesTo + status (no cap check yet).
169	  const matched = incentives.filter((inc) => {
170	    if (inc.status === "ended") return false;
171	    const a = inc.appliesTo;
172	    if (a) {
173	      if (a.models && !a.models.includes(unit.model)) return false;
174	      if (a.trims && !a.trims.includes(unit.trim)) return false;
175	      if (a.years && !a.years.includes(unit.year)) return false;
176	      if (a.provinces && !a.provinces.includes(dealer.province)) return false;
177	    }
178	    return true;
179	  });
180	
181	  // Second pass: drop incentives that fail the post-OEM-cash transaction-
182	  // value cap. Computed once over the matched set.
183	  const adjustedPreTax = effectivePreTaxValue(unit, matched);
184	  return matched.filter((inc) => {
185	    if (
186	      inc.transactionValueCapCad !== undefined &&
187	      inc.capAppliesToImported &&
188	      E_GMP_IS_IMPORTED &&
189	      adjustedPreTax > inc.transactionValueCapCad
190	    ) {
191	      return false;
192	    }
193	    return true;
194	  });
195	}
196	
197	// Helper exposed for UI: how far over the cap is this unit (0 if eligible)?
198	// Uses post-OEM-cash value so it matches the eligibility check.
199	export function evapCapDeltaCad(
200	  unit: InventoryUnit,
201	  evap: Incentive | undefined,
202	  applicable: Incentive[] = [],
203	): number {
204	  if (!evap || evap.transactionValueCapCad === undefined) return 0;
205	  const delta = effectivePreTaxValue(unit, applicable) - evap.transactionValueCapCad;
206	  return delta > 0 ? +delta.toFixed(2) : 0;
207	}
208	
209	// Component scores are 0-1; the composite is a weighted average rendered as 0-100.
210	function priceVsMsrpScore(unit: InventoryUnit): number {
211	  const ratio = unit.dealerAskingPrice / unit.msrp;
212	  // 1.0 = exact MSRP -> 0.5; 5% below MSRP -> ~1.0; 3% above -> ~0.0
213	  const score = 0.5 + (1 - ratio) * 10;
214	  return clamp01(score);
215	}
216	
217	function daysOnLotScore(unit: InventoryUnit): number {
218	  const d = unit.daysOnLot ?? 0;
219	  // 0 days -> 0; 60 days -> ~0.6; 120+ days -> 1.0 (very negotiable)
220	  return clamp01(d / 120);
221	}
222	
223	// "Pressure" = how leverageable a dealer is for a buyer. High pressure when:
224	// they hold a deep cluster of similar trims and at least some are aging out.
225	export function dealerPressureIndex(
226	  unit: InventoryUnit,
227	  dealerUnits: InventoryUnit[],
228	): number {
229	  const sameTrim = dealerUnits.filter(
230	    (u) => u.model === unit.model && u.trim === unit.trim,
231	  );
232	  if (sameTrim.length === 0) return 0;
233	  const depth = Math.min(sameTrim.length / 4, 1); // 4+ same-trim = max depth signal
234	  const avgAge =
235	    sameTrim.reduce((s, u) => s + (u.daysOnLot ?? 0), 0) / sameTrim.length;
236	  const ageSignal = clamp01(avgAge / 90);
237	  // Equal weight; both signals must be present for a high score.
238	  return clamp01(0.5 * depth + 0.5 * ageSignal);
239	}
240	
241	function incentiveStackScore(applicable: Incentive[]): number {
