1	// Data layer: loads JSON from /data and validates with the zod schemas.
2	// Server-only; never imported into a "use client" file.
3	
4	import "server-only";
5	import { promises as fs } from "node:fs";
6	import path from "node:path";
7	import { z } from "zod";
8	
9	import {
10	  DealerSchema,
11	  IncentiveSchema,
12	  InventoryUnitSchema,
13	  MarketIntelSchema,
14	  SnapshotSchema,
15	  SpecSchema,
16	  TaxesAndFeesSchema,
17	  UsedListingSchema,
18	  type Dealer,
19	  type Incentive,
20	  type InventoryUnit,
21	  type MarketIntel,
22	  type ScoredUnit,
23	  type Snapshot,
24	  type Spec,
25	  type TaxesAndFees,
26	  type UsedListing,
27	  type UsedMarketStat,
28	} from "./types";
29	import { MODELS } from "./constants";
30	import { applicableIncentives, computeDealScore, computeOtd } from "./scoring";
31	
32	const DATA_DIR = path.join(process.cwd(), "data");
33	
34	async function readJson<T>(file: string, schema: z.ZodType<T>): Promise<T> {
35	  const raw = await fs.readFile(path.join(DATA_DIR, file), "utf8");
36	  return schema.parse(JSON.parse(raw));
37	}
38	
39	export async function loadDealers(): Promise<Dealer[]> {
40	  return readJson("dealers.json", z.array(DealerSchema));
41	}
42	
43	export async function loadUnits(): Promise<InventoryUnit[]> {
44	  const base = await readJson("units.json", z.array(InventoryUnitSchema));
45	  // Merge per-unit detail-page enrichment (daysOnLot, vin, more accurate
46	  // colors, MSRP overrides). Generated by scripts/enrich_units_from_listings.py.
47	  // Optional: app runs fine without it.
48	  let enrichment: Record<string, Partial<InventoryUnit>> = {};
49	  try {
50	    const raw = await fs.readFile(path.join(DATA_DIR, "units-enrichment.json"), "utf8");
51	    enrichment = JSON.parse(raw) as Record<string, Partial<InventoryUnit>>;
52	  } catch (err) {
53	    if ((err as NodeJS.ErrnoException)?.code !== "ENOENT") throw err;
54	  }
55	  return base.map((u) => {
56	    const e = enrichment[u.id];
57	    if (!e) return u;
58	    // Only allow whitelisted fields to override — never let an enrichment
59	    // file silently change model/year/trim/dealerId.
60	    return {
61	      ...u,
62	      daysOnLot: e.daysOnLot ?? u.daysOnLot,
63	      vin: e.vin ?? u.vin,
64	      msrp: e.msrp ?? u.msrp,
65	      exteriorColor: e.exteriorColor ?? u.exteriorColor,
66	      interiorColor: e.interiorColor ?? u.interiorColor,
67	    };
68	  });
69	}
70	
71	export async function loadIncentives(): Promise<Incentive[]> {
72	  return readJson("incentives.json", z.array(IncentiveSchema));
73	}
74	
75	export async function loadSpecs(): Promise<Spec[]> {
76	  try {
77	    return await readJson("specs.json", z.array(SpecSchema));
78	  } catch (err) {
79	    if ((err as NodeJS.ErrnoException)?.code === "ENOENT") return [];
80	    throw err;
81	  }
82	}
83	
84	export async function loadTaxesAndFees(): Promise<TaxesAndFees | null> {
85	  try {
86	    return await readJson("taxes-and-fees.json", TaxesAndFeesSchema);
87	  } catch (err) {
88	    if ((err as NodeJS.ErrnoException)?.code === "ENOENT") return null;
89	    throw err;
90	  }
91	}
92	
93	export async function loadMarketIntel(): Promise<MarketIntel | null> {
94	  try {
95	    return await readJson("market-intel.json", MarketIntelSchema);
96	  } catch (err) {
97	    if ((err as NodeJS.ErrnoException)?.code === "ENOENT") return null;
98	    throw err;
99	  }
100	}
101	
102	export async function loadUsedListings(): Promise<UsedListing[]> {
103	  try {
104	    return await readJson("used-listings.json", z.array(UsedListingSchema));
105	  } catch (err) {
106	    if ((err as NodeJS.ErrnoException)?.code === "ENOENT") return [];
107	    throw err;
108	  }
109	}
110	
111	// Trims that skew MSRP comparisons because they're priced as halo/performance
112	// variants ($15-25k above the long-range floor). Used to compute a fairer
113	// retention denominator for typical-buyer comparisons.
114	const HALO_TRIM_REGEX = /\b(GT|N|Performance|Calligraphy)\b/i;
115	
116	// Per-model used-market summary used as new-car negotiation leverage data.
117	// retentionPercent = median used / lowest new MSRP. Lower = steeper
118	// depreciation = stronger lever when arguing a new-car discount.
119	//
120	// includeHaloTrims controls whether GT / N / Performance / Calligraphy trims
121	// are eligible to set the new-MSRP floor. Default false because those trims
122	// are usually not what the buyer is shopping and they tank the retention
123	// number to the point of being meaningless.
124	export function computeUsedMarketStats(
125	  used: UsedListing[],
126	  specs: Spec[],
127	  includeHaloTrims = false,
128	): UsedMarketStat[] {
129	  const median = (arr: number[]): number => {
130	    if (!arr.length) return 0;
131	    const sorted = [...arr].sort((a, b) => a - b);
132	    const mid = Math.floor(sorted.length / 2);
133	    return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
134	  };
135	  const newMsrpByModel = new Map<string, number>();
136	  for (const s of specs) {
137	    if (!s.msrpCad) continue;
138	    if (!includeHaloTrims && HALO_TRIM_REGEX.test(s.trim)) continue;
139	    const cur = newMsrpByModel.get(s.model);
140	    if (cur == null || s.msrpCad < cur) newMsrpByModel.set(s.model, s.msrpCad);
141	  }
142	  return MODELS.map((model) => {
143	    const rows = used.filter((u) => u.model === model);
144	    const prices = rows.map((u) => u.priceCad);
145	    const kms = rows.map((u) => u.kmDriven);
146	    const medPrice = median(prices);
147	    const newFloor = newMsrpByModel.get(model) ?? null;
148	    return {
149	      model,
150	      count: rows.length,
151	      medianPriceCad: medPrice,
152	      minPriceCad: prices.length ? Math.min(...prices) : 0,
153	      maxPriceCad: prices.length ? Math.max(...prices) : 0,
154	      medianKm: median(kms),
155	      newMsrpFloorCad: newFloor,
156	      retentionPercent: newFloor && medPrice ? Math.round((medPrice / newFloor) * 100) : null,
157	    };
158	  }).filter((s) => s.count > 0);
159	}
160	
161	export function specKey(model: string, year: number, trim: string, drivetrain: string): string {
162	  return `${model}|${year}|${trim}|${drivetrain}`;
163	}
164	
165	export function specMap(specs: Spec[]): Map<string, Spec> {
166	  return new Map(specs.map((s) => [specKey(s.model, s.year, s.trim, s.drivetrain), s]));
167	}
168	
169	export type DataMeta = {
170	  unitsUpdatedAt: string;
171	  incentivesUpdatedAt: string;
172	  dealersUpdatedAt: string;
173	  snapshotCount: number;
174	  lastSnapshotAt: string | null;
175	};
176	
177	export async function loadMeta(): Promise<DataMeta> {
178	  const [unitsStat, incStat, dealersStat, snaps] = await Promise.all([
179	    fs.stat(path.join(DATA_DIR, "units.json")),
180	    fs.stat(path.join(DATA_DIR, "incentives.json")),
181	    fs.stat(path.join(DATA_DIR, "dealers.json")),
182	    listSnapshotFiles(),
183	  ]);
184	  const lastSnapshotAt = snaps.length
185	    ? (await fs.stat(path.join(DATA_DIR, "snapshots", snaps[snaps.length - 1]))).mtime.toISOString()
186	    : null;
187	  return {
188	    unitsUpdatedAt: unitsStat.mtime.toISOString(),
189	    incentivesUpdatedAt: incStat.mtime.toISOString(),
190	    dealersUpdatedAt: dealersStat.mtime.toISOString(),
191	    snapshotCount: snaps.length,
192	    lastSnapshotAt,
193	  };
194	}
195	
196	export async function listSnapshotFiles(): Promise<string[]> {
197	  const dir = path.join(DATA_DIR, "snapshots");
198	  try {
199	    const entries = await fs.readdir(dir);
200	    return entries
201	      .filter((e) => e.endsWith(".json"))
202	      .sort();
203	  } catch {
204	    return [];
205	  }
206	}
207	
208	export async function loadSnapshots(limit?: number): Promise<Snapshot[]> {
209	  const files = await listSnapshotFiles();
210	  const slice = limit ? files.slice(-limit) : files;
211	  return Promise.all(
212	    slice.map((f) =>
213	      readJson(path.join("snapshots", f), SnapshotSchema),
214	    ),
215	  );
216	}
217	
218	// Consolidated dataset: every unit decorated with OTD, deal score, and the
219	// incentives that apply. This is the single source of truth all UI reads from.
220	//
221	// buyerProvince controls the sales-tax basis + transport-cost line. When
222	// omitted (e.g. older callers), each unit's OTD assumes the buyer is in
223	// the dealer's province — the legacy pre-2026-05 behavior.
224	export async function loadScoredUnits(buyerProvince?: import("./constants").Province): Promise<{
225	  units: ScoredUnit[];
226	  dealers: Dealer[];
227	  dealerById: Map<string, Dealer>;
228	  incentives: Incentive[];
229	  buyerProvince: import("./constants").Province | null;
230	}> {
231	  const [units, dealers, incentives] = await Promise.all([
232	    loadUnits(),
233	    loadDealers(),
234	    loadIncentives(),
235	  ]);
236	  const dealerById = new Map(dealers.map((d) => [d.id, d]));
237	  const unitsByDealer = new Map<string, InventoryUnit[]>();
238	  for (const u of units) {
239	    const arr = unitsByDealer.get(u.dealerId) ?? [];
240	    arr.push(u);
241	    unitsByDealer.set(u.dealerId, arr);
242	  }
243	
244	  const scored = units.map((unit) => {
245	    const dealer = dealerById.get(unit.dealerId);
246	    if (!dealer) {
247	      throw new Error(`Unit ${unit.id} references unknown dealer ${unit.dealerId}`);
248	    }
249	    const applicable = applicableIncentives(unit, dealer, incentives);
250	    const otdBreakdown = computeOtd(unit, dealer, applicable, buyerProvince);
251	    const { score, breakdown } = computeDealScore({
252	      unit,
253	      dealer,
254	      dealerUnits: unitsByDealer.get(dealer.id) ?? [],
255	      applicable,
256	    });
257	    return {
258	      ...unit,
259	      otdCad: otdBreakdown.total,
260	      otdBreakdown,
261	      dealScore: score,
262	      dealScoreBreakdown: breakdown,
263	      applicableIncentives: applicable,
264	    } satisfies ScoredUnit;
265	  });
266	
267	  return { units: scored, dealers, dealerById, incentives, buyerProvince: buyerProvince ?? null };
268	}
