// Data layer: loads JSON from /data and validates with the zod schemas.
// Server-only; never imported into a "use client" file.

import "server-only";
import { promises as fs } from "node:fs";
import path from "node:path";
import { z } from "zod";

import {
  DealerSchema,
  IncentiveSchema,
  InventoryUnitSchema,
  MarketIntelSchema,
  SnapshotSchema,
  SpecSchema,
  TaxesAndFeesSchema,
  UsedListingSchema,
  type Dealer,
  type Incentive,
  type InventoryUnit,
  type MarketIntel,
  type ScoredUnit,
  type Snapshot,
  type Spec,
  type TaxesAndFees,
  type UsedListing,
  type UsedMarketStat,
} from "./types";
import { MODELS } from "./constants";
import { applicableIncentives, computeDealScore, computeOtd } from "./scoring";

const DATA_DIR = path.join(process.cwd(), "data");

async function readJson<T>(file: string, schema: z.ZodType<T>): Promise<T> {
  const raw = await fs.readFile(path.join(DATA_DIR, file), "utf8");
  return schema.parse(JSON.parse(raw));
}

export async function loadDealers(): Promise<Dealer[]> {
  return readJson("dealers.json", z.array(DealerSchema));
}

export async function loadUnits(): Promise<InventoryUnit[]> {
  const base = await readJson("units.json", z.array(InventoryUnitSchema));
  // Merge per-unit detail-page enrichment (daysOnLot, vin, more accurate
  // colors, MSRP overrides). Generated by scripts/enrich_units_from_listings.py.
  // Optional: app runs fine without it.
  let enrichment: Record<string, Partial<InventoryUnit>> = {};
  try {
    const raw = await fs.readFile(path.join(DATA_DIR, "units-enrichment.json"), "utf8");
    enrichment = JSON.parse(raw) as Record<string, Partial<InventoryUnit>>;
  } catch (err) {
    if ((err as NodeJS.ErrnoException)?.code !== "ENOENT") throw err;
  }
  return base.map((u) => {
    const e = enrichment[u.id];
    if (!e) return u;
    // Only allow whitelisted fields to override — never let an enrichment
    // file silently change model/year/trim/dealerId.
    return {
      ...u,
      daysOnLot: e.daysOnLot ?? u.daysOnLot,
      vin: e.vin ?? u.vin,
      msrp: e.msrp ?? u.msrp,
      exteriorColor: e.exteriorColor ?? u.exteriorColor,
      interiorColor: e.interiorColor ?? u.interiorColor,
    };
  });
}

