87	// E-GMP ICCU recall family. Ioniq 5 spans 2025; EV6 + Ioniq 6 stop at 2024.
88	// Source: data/market-intel.json (kept in sync there).
89	function iccuAffected(model: Model, year: number): boolean {
90	  if (model === "EV6" && year >= 2022 && year <= 2024) return true;
91	  if (model === "Ioniq5" && year >= 2022 && year <= 2025) return true;
92	  if (model === "Ioniq6" && year >= 2023 && year <= 2024) return true;
93	  return false;
94	}
