98	const CSV_COLS = [
99	  "model", "year", "trim", "drivetrain", "exteriorColor", "interiorColor",
100	  "msrp", "asking", "otd", "daysOnLot", "lastSeen", "status",
101	  "dealerName", "dealerCity", "dealerProvince", "dealerPhone", "pressure",
102	  "listingUrl",
