105	function csvEscape(val: string | number | undefined | null): string {
106	  if (val === undefined || val === null) return "";
107	  const s = String(val);
108	  if (s.includes(",") || s.includes('"') || s.includes("\n")) {
109	    return `"${s.replace(/"/g, '""')}"`;
110	  }
111	  return s;
112	}
