114	function modelBreakdown(units: ScoredUnit[]): string {
115	  const counts: Record<Model, number> = { EV6: 0, Ioniq5: 0, Ioniq6: 0, EV9: 0, Ioniq9: 0 };
116	  for (const u of units) counts[u.model] += 1;
117	  return (Object.keys(counts) as Model[])
118	    .filter((m) => counts[m] > 0)
119	    .map((m) => `${counts[m]} ${MODEL_LABEL[m]}`)
120	    .join(", ");
121	}
