123	function activeFilterChips(s: {
124	  model: Model | "all";
125	  year: number | "all";
126	  drivetrain: "RWD" | "AWD" | "all";
127	  region: "ggh" | "on" | "all";
128	  maxPrice: number | "";
129	  pressureOnly: boolean;
130	  evapOnly: boolean;
131	  query: string;
132	}): { key: string; label: string }[] {
133	  const out: { key: string; label: string }[] = [];
134	  if (s.model !== "all") out.push({ key: "model", label: MODEL_LABEL[s.model] });
135	  if (s.year !== "all") out.push({ key: "year", label: `MY ${s.year}` });
136	  if (s.drivetrain !== "all") out.push({ key: "drivetrain", label: s.drivetrain });
137	  if (s.region !== "ggh") out.push({ key: "region", label: s.region === "on" ? "All Ontario" : "All Canada" });
138	  if (s.maxPrice !== "") out.push({ key: "maxPrice", label: `≤ $${s.maxPrice.toLocaleString("en-CA")}` });
139	  if (s.pressureOnly) out.push({ key: "pressureOnly", label: "High pressure" });
140	  if (s.evapOnly) out.push({ key: "evapOnly", label: "EVAP eligible" });
141	  if (s.query.trim()) out.push({ key: "query", label: `"${s.query.trim()}"` });
142	  return out;
143	}
