145	function exportCsv(
146	  units: ScoredUnit[],
147	  dealerById: Map<string, Dealer>,
148	  pressureByDealer: Record<string, number>,
149	) {
150	  const header = CSV_COLS.join(",");
151	  const rows = units.map((u) => {
152	    const d = dealerById.get(u.dealerId);
153	    return [
154	      u.model, u.year, u.trim, u.drivetrain, u.exteriorColor, u.interiorColor,
155	      u.msrp, u.dealerAskingPrice, u.otdCad, u.daysOnLot ?? "", u.lastSeen, u.status,
156	      d?.name ?? "", d?.city ?? "", d?.province ?? "", d?.phone ?? "", pressureByDealer[u.dealerId] ?? 0,
157	      u.listingUrl ?? "",
158	    ].map(csvEscape).join(",");
159	  });
160	  const csv = [header, ...rows].join("\n");
161	  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
162	  const url = URL.createObjectURL(blob);
163	  const today = new Date().toISOString().slice(0, 10).replace(/-/g, "");
164	  const a = document.createElement("a");
165	  a.href = url;
166	  a.download = `ev-inventory-${today}.csv`;
167	  document.body.appendChild(a);
168	  a.click();
169	  document.body.removeChild(a);
170	  URL.revokeObjectURL(url);
171	}
