502	                      <span className="chip-warn block w-fit">Aging MY{String(u.year).slice(-2)}</span>
503	                    )}
504	                    {stale && (
505	                      <span
506	                        className="chip-neutral block w-fit text-fg-subtle"
507	                        title={`Last seen ${daysSince(u.lastSeen)} days ago — may have sold. Verify before quoting.`}
508	                      >
509	                        Stale {daysSince(u.lastSeen)}d
510	                      </span>
511	                    )}
512	                    {iccuAffected(u.model, u.year) && (
513	                      <span
514	                        className="chip-bad block w-fit"
515	                        title="E-GMP ICCU recall family. Demand written confirmation that ICCU software flash + module inspection have been completed before contracting. 15-yr/290k-km warranty extension applies."
516	                      >
517	                        ICCU recall
518	                      </span>
519	                    )}
520	                  </td>
521	                  <td className="px-3 py-2 text-xs">
522	                    <div className="font-medium">{dealer?.name ?? "—"}</div>
523	                    <div className="text-fg-subtle">{dealer?.city}, {dealer?.province}</div>
524	                  </td>
525	                  <td className="px-3 py-2 text-right num">
526	                    <span className={pressure >= 70 ? "text-accent" : pressure >= 40 ? "text-warn" : "text-fg-muted"}>
527	                      {pressure}
528	                    </span>
529	                  </td>
530	                  <td className="px-3 py-2 text-right">
531	                    {u.listingUrl ? (
532	                      <a
533	                        href={u.listingUrl}
534	                        target="_blank"
535	                        rel="noreferrer"
536	                        onClick={(e) => e.stopPropagation()}
537	                        className="text-xxs text-accent hover:text-accent-strong inline-block px-1.5 py-0.5 border border-border rounded"
538	                        title="Open AutoTrader listing in new tab"
539	                      >
540	                        Listing ↗
541	                      </a>
542	                    ) : null}
543	                  </td>
544	                </tr>
545	              );
546	            })}
547	            {filtered.length === 0 && (
548	              <tr>
549	                <td colSpan={13} className="px-3 py-12 text-center text-fg-muted">
550	                  No units match these filters.
551	                </td>
552	              </tr>
553	            )}
554	          </tbody>
555	        </table>
556	      </div>
557	      <UnitDrawer
558	        unit={selected}
559	        dealer={selected ? dealerById.get(selected.dealerId) : undefined}
560	        pressure={selected ? dealerPressureByDealer[selected.dealerId] ?? 0 : 0}
561	        comparable={comparable}
562	        comparableDealer={comparable ? dealerById.get(comparable.dealerId) : undefined}
563	        onClose={() => setSelectedId(null)}
564	        onNavigate={(dir) => {
565	          if (!selected || filtered.length === 0) return;
566	          const idx = filtered.findIndex((u) => u.id === selected.id);
567	          if (idx === -1) return;
568	          const next = (idx + dir + filtered.length) % filtered.length;
569	          setSelectedId(filtered[next].id);
570	        }}
571	        position={
572	          selected
573	            ? {
574	                index: Math.max(0, filtered.findIndex((u) => u.id === selected.id)),
575	                total: filtered.length,
576	              }
577	            : undefined
578	        }
579	      />
580	    </div>
581	  );
582	}
