470	              const pressure = dealerPressureByDealer[u.dealerId] ?? 0;
471	              const isActive = u.id === selectedId;
472	              const fav = isFavorite(u.id);
473	              const stale = daysSince(u.lastSeen) > 7;
474	              return (
475	                <tr
476	                  key={u.id}
477	                  className={`border-t border-border cursor-pointer ${isActive ? "bg-accent-dim/20" : "card-hover"}`}
478	                  onClick={() => setSelectedId(u.id)}
479	                >
480	                  <td className="px-2 py-2 text-center">
481	                    <button
482	                      type="button"
483	                      onClick={(e) => { e.stopPropagation(); toggleFavorite(u.id); }}
484	                      className={`text-base leading-none ${fav ? "text-warn" : "text-fg-subtle hover:text-fg-muted"}`}
485	                      title={fav ? "Remove from favorites" : "Add to favorites"}
486	                      aria-label={fav ? "Unstar" : "Star"}
487	                    >
488	                      {fav ? "★" : "☆"}
489	                    </button>
490	                  </td>
491	                  <td className="px-3 py-2"><DealScoreBadge score={u.dealScore} /></td>
492	                  <td className="px-3 py-2">
493	                    <div className="font-medium">{MODEL_LABEL[u.model]}</div>
494	                    <div className="text-xxs text-fg-muted">{u.trim} · {u.drivetrain}</div>
495	                  </td>
496	                  <td className="px-3 py-2 num">{u.year}</td>
497	                  <td className="px-3 py-2 text-xs">
498	                    <div>{u.exteriorColor}</div>
499	                    <div className="text-fg-subtle">{u.interiorColor}</div>
500	                  </td>
501	                  <td className="px-3 py-2 text-right num">{fmtCad(u.msrp)}</td>
502	                  <td className="px-3 py-2 text-right num">
503	                    {fmtCad(u.dealerAskingPrice)}
504	                    {u.dealerAskingPrice < u.msrp && (
505	                      <div className="text-xxs text-accent">
506	                        −{fmtCad(u.msrp - u.dealerAskingPrice)}
507	                      </div>
508	                    )}
509	                    {u.dealerAskingPrice > u.msrp + 5000 && (
510	                      <div
511	                        className="text-xxs text-warn"
512	                        title="Asking price exceeds MSRP by >$5k. Likely a higher trim mis-mapped to a base trim, or a stale MSRP default. Treat the discount math as suspect until verified on the OEM configurator."
513	                      >
514	                        MSRP unverified
515	                      </div>
516	                    )}
517	                  </td>
518	                  <td className="px-3 py-2 text-right num font-medium">
519	                    {fmtCad(u.otdCad)}
520	                    <EvapChip state={evapStateFor(u)} unit={u} />
521	                  </td>
522	                  <td className="px-3 py-2 text-right num text-xs" title={rangeFor(u.id) ? `Range ${rangeFor(u.id)} km (NRCan/EPA combined)` : "Range spec missing"}>
523	                    {(() => {
524	                      const p = perKmFor(u);
525	                      return p ? `$${p.toFixed(0)}` : "—";
526	                    })()}
527	                  </td>
528	                  <td className="px-3 py-2 text-right num">{u.daysOnLot ?? "—"}</td>
529	                  <td className="px-3 py-2 space-y-1">
530	                    <StatusChip status={u.status} />
531	                    {isAgingOutgoing(u.year, u.daysOnLot) && (
532	                      <span className="chip-warn block w-fit">Aging MY{String(u.year).slice(-2)}</span>
533	                    )}
534	                    {stale && (
535	                      <span
536	                        className="chip-neutral block w-fit text-fg-subtle"
537	                        title={`Last seen ${daysSince(u.lastSeen)} days ago — may have sold. Verify before quoting.`}
538	                      >
539	                        Stale {daysSince(u.lastSeen)}d
540	                      </span>
541	                    )}
542	                    {iccuAffected(u.model, u.year) && (
543	                      <span
544	                        className="chip-bad block w-fit"
545	                        title="E-GMP ICCU recall family. Demand written confirmation that ICCU software flash + module inspection have been completed before contracting. 15-yr/290k-km warranty extension applies."
546	                      >
547	                        ICCU recall
548	                      </span>
549	                    )}
550	                  </td>
551	                  <td className="px-3 py-2 text-xs">
552	                    <div className="font-medium">{dealer?.name ?? "—"}</div>
553	                    <div className="text-fg-subtle">{dealer?.city}, {dealer?.province}</div>
554	                  </td>
555	                  <td className="px-3 py-2 text-right num">
556	                    <span className={pressure >= 70 ? "text-accent" : pressure >= 40 ? "text-warn" : "text-fg-muted"}>
557	                      {pressure}
558	                    </span>
559	                  </td>
560	                  <td className="px-3 py-2 text-right">
561	                    {u.listingUrl ? (
562	                      <a
563	                        href={u.listingUrl}
564	                        target="_blank"
565	                        rel="noreferrer"
566	                        onClick={(e) => e.stopPropagation()}
567	                        className="text-xxs text-accent hover:text-accent-strong inline-block px-1.5 py-0.5 border border-border rounded"
568	                        title="Open AutoTrader listing in new tab"
569	                      >
570	                        Listing ↗
571	                      </a>
572	                    ) : null}
573	                  </td>
574	                </tr>
575	              );
576	            })}
577	            {filtered.length === 0 && (
578	              <tr>
579	                <td colSpan={14} className="px-3 py-12 text-center text-fg-muted">
580	                  No units match these filters.
581	                </td>
582	              </tr>
583	            )}
584	          </tbody>
585	        </table>
586	      </div>
587	      <UnitDrawer
588	        unit={selected}
589	        dealer={selected ? dealerById.get(selected.dealerId) : undefined}
590	        pressure={selected ? dealerPressureByDealer[selected.dealerId] ?? 0 : 0}
591	        comparable={comparable}
592	        comparableDealer={comparable ? dealerById.get(comparable.dealerId) : undefined}
593	        onClose={() => setSelectedId(null)}
594	        onNavigate={(dir) => {
595	          if (!selected || filtered.length === 0) return;
596	          const idx = filtered.findIndex((u) => u.id === selected.id);
597	          if (idx === -1) return;
598	          const next = (idx + dir + filtered.length) % filtered.length;
599	          setSelectedId(filtered[next].id);
600	        }}
601	        position={
602	          selected
603	            ? {
604	                index: Math.max(0, filtered.findIndex((u) => u.id === selected.id)),
605	                total: filtered.length,
606	              }
607	            : undefined
608	        }
609	      />
610	    </div>
611	  );
612	}
