// Data layer: loads JSON from /data and validates with the zod schemas.
// Server-only; never imported into a "use client" file.

import "server-only";
import { promises as fs } from "node:fs";
import path from "node:path";
import { z } from "zod";

import {
  DealerSchema,
  IncentiveSchema,
  InventoryUnitSchema,
  MarketIntelSchema,
  SnapshotSchema,
  SpecSchema,
  TaxesAndFeesSchema,
  UsedListingSchema,
  type Dealer,
  type Incentive,
  type InventoryUnit,
  type MarketIntel,
  type ScoredUnit,
  type Snapshot,
  type Spec,
  type TaxesAndFees,
  type UsedListing,
  type UsedMarketStat,
} from "./types";
import { MODELS } from "./constants";
import { applicableIncentives, computeDealScore, computeOtd } from "./scoring";

const DATA_DIR = path.join(process.cwd(), "data");

async function readJson<T>(file: string, schema: z.ZodType<T>): Promise<T> {
  const raw = await fs.readFile(path.join(DATA_DIR, file), "utf8");
  return schema.parse(JSON.parse(raw));
}

export async function loadDealers(): Promise<Dealer[]> {
  const base = await readJson("dealers.json", z.array(DealerSchema));
  // Backfill dealer phone + address from per-listing enrichment when the
  // canonical dealers.json still has placeholder values. Unit→dealer map
  // built from units.json so we know which enrichment entry belongs to whom.
  let enrichment: Record<string, { phone?: string; streetAddress?: string }> = {};
  let unitsRaw: Array<{ id: string; dealerId: string }> = [];
  try {
    enrichment = JSON.parse(
      await fs.readFile(path.join(DATA_DIR, "units-enrichment.json"), "utf8"),
    );
