// Trims that skew MSRP comparisons because they're priced as halo/performance
// variants ($15-25k above the long-range floor). Used to compute a fairer
// retention denominator for typical-buyer comparisons.
const HALO_TRIM_REGEX = /\b(GT|N|Performance|Calligraphy)\b/i;

// Per-model used-market summary used as new-car negotiation leverage data.
// retentionPercent = median used / lowest new MSRP. Lower = steeper
// depreciation = stronger lever when arguing a new-car discount.
//
// includeHaloTrims controls whether GT / N / Performance / Calligraphy trims
// are eligible to set the new-MSRP floor. Default false because those trims
// are usually not what the buyer is shopping and they tank the retention
// number to the point of being meaningless.
export function computeUsedMarketStats(
  used: UsedListing[],
  specs: Spec[],
  includeHaloTrims = false,
): UsedMarketStat[] {
  const median = (arr: number[]): number => {
    if (!arr.length) return 0;
    const sorted = [...arr].sort((a, b) => a - b);
    const mid = Math.floor(sorted.length / 2);
    return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
  };
  const newMsrpByModel = new Map<string, number>();
  for (const s of specs) {
    if (!s.msrpCad) continue;
    if (!includeHaloTrims && HALO_TRIM_REGEX.test(s.trim)) continue;
    const cur = newMsrpByModel.get(s.model);
    if (cur == null || s.msrpCad < cur) newMsrpByModel.set(s.model, s.msrpCad);
  }
