(() => {
  if (window.__capturedGql) return 'already installed: ' + window.__capturedGql.length + ' captured';
  window.__capturedGql = [];
  const origFetch = window.fetch;
  window.fetch = function(input, init) {
    try {
      const url = typeof input === 'string' ? input : input.url;
      if (url && url.includes('graphql')) {
        const body = init && init.body ? (typeof init.body === 'string' ? init.body : '[non-string body]') : null;
        const entry = { url, body: body ? body.slice(0, 4000) : null, headers: init && init.headers ? Object.fromEntries(new Headers(init.headers).entries()) : null };
        return origFetch.apply(this, arguments).then(r => {
          const clone = r.clone();
          clone.text().then(text => { entry.responseSnippet = text.slice(0, 2000); entry.responseLength = text.length; window.__capturedGql.push(entry); });
          return r;
        });
      }
    } catch(e) {}
    return origFetch.apply(this, arguments);
  };
  return 'fetch hook installed';
})()

(() => {
  const out = {};
  out.hasNextData = !!document.getElementById('__NEXT_DATA__');
  out.nextDataLen = out.hasNextData ? document.getElementById('__NEXT_DATA__').textContent.length : 0;
  if (out.hasNextData) {
    try {
      const nd = JSON.parse(document.getElementById('__NEXT_DATA__').textContent);
      out.topKeys = Object.keys(nd);
      out.propsKeys = nd.props ? Object.keys(nd.props) : null;
      out.pagePropsKeys = nd.props && nd.props.pageProps ? Object.keys(nd.props.pageProps) : null;
      const pp = nd.props && nd.props.pageProps;
      if (pp) {
        for (const k of Object.keys(pp)) {
          if (Array.isArray(pp[k])) out[`pp.${k}.len`] = pp[k].length;
          else if (pp[k] && typeof pp[k] === 'object') out[`pp.${k}.keys`] = Object.keys(pp[k]).slice(0,15);
        }
      }
    } catch(e) { out.parseErr = String(e); }
  }
  out.allDataIds = Array.from(document.querySelectorAll('script[id]')).map(s => s.id);
  return JSON.stringify(out, null, 2);
})()

(() => {
  const nd = JSON.parse(document.getElementById('__NEXT_DATA__').textContent);
  const pp = nd.props.pageProps;
  const out = {
    numberOfResults: pp.numberOfResults,
    numberOfPages: pp.numberOfPages,
    listingsCount: pp.listings ? pp.listings.length : 0,
  };
  if (pp.listings && pp.listings[0]) {
    const l0 = pp.listings[0];
    out.firstListingKeys = Object.keys(l0);
    // probe interesting fields
    const probe = ['id','listingId','vin','vehicleIdentificationNumber','daysOnMarket','daysOnLot','postedDate','listedAt','phone','dealerPhone','telephoneNumber','dealer','dealerName','dealerId','seller','msrp','price','askingPrice','listingUrl','url','permalink','make','model','trim','year','exteriorColor','exteriorColour','interiorColor','interiorColour','mileage','odometer','kilometres'];
    out.fieldHits = {};
    for (const k of probe) {
      if (l0[k] !== undefined) out.fieldHits[k] = typeof l0[k] === 'object' ? JSON.stringify(l0[k]).slice(0,200) : l0[k];
    }
    out.firstListingSample = JSON.stringify(l0, null, 2).slice(0, 3000);
  }
  return JSON.stringify(out, null, 2);
})()

(() => {
  const nd = JSON.parse(document.getElementById('__NEXT_DATA__').textContent);
  const l = nd.props.pageProps.listings[0];
  return JSON.stringify({
