(() => {
  const nd = JSON.parse(document.getElementById('__NEXT_DATA__').textContent);
  const l = nd.props.pageProps.listings[0];
  const out = {};
  // statistics body
  out.statistics = l.statistics;
  // vehicleDetails sample (numeric-keyed) — sanitize
  if (l.vehicleDetails) {
    out.vehicleDetailsArr = Object.values(l.vehicleDetails).map(v => {
      if (v && typeof v === 'object') return { keys: Object.keys(v).slice(0,10), preview: JSON.stringify(v).replace(/[a-zA-Z0-9_\-]{16,}/g, '<REDACTED>').slice(0, 300) };
      return v;
    });
  }
  // tracking
  out.tracking = l.tracking;
  // url + identifier
  out.url = l.url;
  out.identifier = l.identifier;
  // search top-level for date-ish keys deep in the listing
  function findDateish(obj, path, hits, depth) {
    if (depth > 5 || !obj || typeof obj !== 'object') return;
    for (const k of Object.keys(obj)) {
      const lk = k.toLowerCase();
      if (lk.includes('date') || lk.includes('day') || lk.includes('age') || lk.includes('post') || lk.includes('list') || lk.includes('publish') || lk.includes('creat')) {
        hits.push({ path: path + '.' + k, value: typeof obj[k] === 'object' ? '[obj]' : obj[k] });
      }
      if (typeof obj[k] === 'object') findDateish(obj[k], path + '.' + k, hits, depth + 1);
    }
  }
  const hits = []; findDateish(l, 'listing', hits, 0);
  out.dateish = hits.slice(0, 50);
  // Captured GQL?
  out.capturedGqlCount = (window.__capturedGql || []).length;
  out.capturedGqlUrls = (window.__capturedGql || []).map(g => g.url);
  return JSON.stringify(out, null, 2).slice(0, 6000);
})()

