(function(){
  if (window.__hookInstalled) return "already installed";
  window.__capturedGql = [];
  const origFetch = window.fetch;
  window.fetch = async function(input, init){
    const url = typeof input === 'string' ? input : (input && input.url) || '';
    const isGql = /graphql|listing-search-api/i.test(url);
    let reqBody = null;
    if (isGql && init && init.body) {
      try { reqBody = typeof init.body === 'string' ? init.body : JSON.stringify(init.body); } catch(e){}
    }
    const resp = await origFetch.apply(this, arguments);
    if (isGql) {
      try {
        const cloned = resp.clone();
        const txt = await cloned.text();
        window.__capturedGql.push({
          url: url,
          method: (init && init.method) || 'GET',
          status: resp.status,
          reqBody: reqBody ? reqBody.slice(0, 4000) : null,
          respBody: txt.slice(0, 8000),
          ts: Date.now()
        });
      } catch(e) {
        window.__capturedGql.push({url, error: String(e), ts: Date.now()});
      }
    }
    return resp;
  };
  // Also patch XHR
  const OrigXHR = window.XMLHttpRequest;
  function PatchedXHR(){
    const xhr = new OrigXHR();
    let _url = ''; let _method = 'GET'; let _reqBody = null;
    const origOpen = xhr.open;
    xhr.open = function(method, url){ _method = method; _url = url; return origOpen.apply(xhr, arguments); };
    const origSend = xhr.send;
    xhr.send = function(body){
      if (/graphql|listing-search-api/i.test(_url) && body) {
        try { _reqBody = typeof body === 'string' ? body : JSON.stringify(body); } catch(e){}
      }
      xhr.addEventListener('loadend', function(){
        if (/graphql|listing-search-api/i.test(_url)) {
          window.__capturedGql.push({
            url: _url, method: _method, status: xhr.status,
            reqBody: _reqBody ? _reqBody.slice(0, 4000) : null,
            respBody: (xhr.responseText || '').slice(0, 8000),
            ts: Date.now(), via: 'xhr'
          });
        }
      });
      return origSend.apply(xhr, arguments);
    };
    return xhr;
  }
  window.XMLHttpRequest = PatchedXHR;
  window.__hookInstalled = true;
  return "hook installed";
})();

